const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '4 列' },
      { kind: 'text', payload: '6 行 · 共 24 格' }
    ];
  },
  render: function (input, metrics) {
    var R = function (v) { return Math.round(v * 100) / 100; };
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    if (!isFinite(W) || W <= 0) { W = 400; }
    if (!isFinite(H) || H <= 0) { H = 600; }

    var rows = 6;
    var cols = 4;
    var margin = Math.max(8, Math.min(W, H) * 0.06);
    var topSpace = Math.max(16, H * 0.07);
    var bottomSpace = Math.max(16, H * 0.07);
    var availW = W - 2 * margin;
    var availH = H - 2 * margin - topSpace - bottomSpace;
    var cell = Math.min(availW / cols, availH / rows);
    if (!isFinite(cell) || cell <= 0) { cell = Math.min(availW, availH) / rows; }
    if (!isFinite(cell) || cell <= 0) { cell = Math.min(W, H) / 12; }

    var gridW = cell * cols;
    var gridH = cell * rows;
    var x0 = (W - gridW) / 2;
    var y0 = margin + topSpace + (availH - gridH) / 2;

    var rect = function (x, y, w, h) {
      return [
        ['M', R(x), R(y)],
        ['L', R(x + w), R(y)],
        ['L', R(x + w), R(y + h)],
        ['L', R(x), R(y + h)],
        ['Z']
      ];
    };

    var paths = [];
    var children = [];
    var r, c, x, y, id;

    for (r = 0; r < rows; r++) {
      for (c = 0; c < cols; c++) {
        x = x0 + c * cell;
        y = y0 + r * cell;
        id = 'cell-r' + r + '-c' + c;
        paths.push({ id: id, commands: rect(x, y, cell, cell) });
        children.push({ type: 'path', pathId: id, fill: '#FFFFFF' });
      }
    }

    var t = Math.max(1, cell * 0.03);
    var k, vx, hy, gid;

    for (k = 0; k <= cols; k++) {
      vx = x0 + k * cell;
      gid = 'vline-' + k;
      paths.push({ id: gid, commands: rect(vx - t / 2, y0 - t / 2, t, gridH + t) });
      children.push({ type: 'path', pathId: gid, fill: '#26354A' });
    }

    for (k = 0; k <= rows; k++) {
      hy = y0 + k * cell;
      gid = 'hline-' + k;
      paths.push({ id: gid, commands: rect(x0 - t / 2, hy - t / 2, gridW + t, t) });
      children.push({ type: 'path', pathId: gid, fill: '#26354A' });
    }

    children.push({
      type: 'label',
      contentId: metrics[0].contentId,
      anchor: { x: R(x0 + gridW / 2), y: R(y0 - Math.max(6, topSpace * 0.25)) },
      hAlign: 'center',
      vAlign: 'bottom',
      color: '#26354A'
    });

    children.push({
      type: 'label',
      contentId: metrics[1].contentId,
      anchor: { x: R(x0 + gridW / 2), y: R(y0 + gridH + Math.max(6, bottomSpace * 0.25)) },
      hAlign: 'center',
      vAlign: 'top',
      color: '#26354A'
    });

    return {
      schemaVersion: 1,
      sceneId: 'grid-6x4-24cells',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
